import type { ObjectiveOption } from '@/lib/domain/objective-option';

/** Wire contracts for `/api/v1/objectives`. */

export type ObjectiveDto = Omit<ObjectiveOption, 'accountId'>;

function record(value: unknown, allowed: readonly string[]): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError('Expected an object.');
  const source = value as Record<string, unknown>;
  for (const key of Object.keys(source)) if (!allowed.includes(key)) throw new TypeError('Unknown field.');
  return source;
}

/** The ID is generated by the server; the body carries only the label. */
export function parseAddObjectiveRequest(value: unknown): { label: string } {
  const v = record(value, ['label']);
  if (typeof v.label !== 'string' || v.label.length > 200) throw new TypeError('Invalid label.');
  return { label: v.label };
}

export function parseObjectiveDto(value: unknown): ObjectiveDto {
  const o = record(value, ['id', 'accountId', 'label', 'normalizedLabel', 'origin', 'archivedAt', 'createdAt', 'updatedAt']);
  return {
    id: String(o.id), label: String(o.label), normalizedLabel: String(o.normalizedLabel),
    origin: o.origin === 'SYSTEM' ? 'SYSTEM' : 'CUSTOM', archivedAt: o.archivedAt == null ? null : String(o.archivedAt),
    createdAt: String(o.createdAt), updatedAt: String(o.updatedAt),
  };
}

export function parseObjectiveListDto(value: unknown): { items: ObjectiveDto[] } {
  const v = record(value, ['items']);
  if (!Array.isArray(v.items)) throw new TypeError('Invalid list.');
  return { items: v.items.map(parseObjectiveDto) };
}
